#include <complex>
#include <FArray.hpp>

std::complex<double> Ltm1(int bx, int by, double x, double y, FArray1D<std::complex<double>>& xInt) {
  std::complex<double> Ltm1_result;

  Ltm1_result = xInt(by) - xInt(bx);

  return Ltm1_result;
}

std::complex<double> Lt0(int bx, int by, double x, double y, FArray1D<std::complex<double>>& xInt) {
  std::complex<double> Lt0_result;

  Lt0_result = y / (y - x) * Ltm1(bx, by, x, y, xInt);

  return Lt0_result;
}

std::complex<double> Lt1(int bx, int by, double x, double y, FArray1D<std::complex<double>>& xInt) {
  std::complex<double> Lt1_result;

  Lt1_result = y / (y - x) * (Lt0(bx, by, x, y, xInt) + 1.0);  // @coverage-probe

  return Lt1_result;
}

